-- 0140: the near-synonym sets of Ghāfir 40:2–3 into AL's furūq layer (80-KIN). AL had six DRAFT sets for these
-- themes with no glosses (nuance_note = the set name) and staging lemma ids (ALL:NS:*); QR had six curated sets
-- (qr_sarf_near). Each member checked against al-Rāghib, Ibn Fāris, the other lexicons and Lane (English):
--   member      → canonical GLOBAL lemma id (AL:LEMMA); staging ids resolved through merged_into
--   basic_gloss → plain English for a beginner; contrast_note → what sets it apart in its set
--   member_src  → the lexicon/tafsīr lines that back it (block id + page, for the backlink)
--   evidence    → its Qurʾān verse, cut from the muṣḥaf
--   set_src     → the set's "what tells them apart" line, with its source
-- Fixes: بَأْس is not "sudden" (no book says it) → "a hard, crushing blow"; نَزَّلَ "in parts" is disputed → hedged;
-- «أَصْفَحَ» → صَفَحَ (the Qurʾān has Form I only; Form IV = "turned a beggar away", Lane p.1695); تَصَدَّقَ is not a
-- word for forgiving → rejected in that set. Added: خَطِيئَة (sin), فَضْل (bounty), نَزَّلَ (sending down).
-- al-ʿAskarī's al-Furūq is not in the corpus.
UPDATE ar_ling_root_lemma SET merged_into = '92c86e0a535b58b80a741edc4f' WHERE id = 'ALL:NS:223CA78A3EA4F605' AND merged_into IS NULL;
UPDATE ar_ling_root_lemma SET merged_into = 'eb5da06d9eac0f09c6549a5c6f', note_md = coalesce(note_md || ' ', '') || 'Listed as «أَصْفَحَ»; the Qurʾān has Form I صَفَحَ only (0140).' WHERE id = 'ALL:NS:CCFC9A7BBF4414E9' AND merged_into IS NULL;
UPDATE ar_ling_root_lemma_furuq_set SET canonical_ar = 'الذَّنْبُ وَأَخَوَاتُهُ', updated_at = datetime('now') WHERE id = 'NS:SIN:SIN' AND canonical_ar IS NULL;
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:NS:SIN:SIN:contrast', 'NS:SIN:SIN', 'kmaps_synth', 'contrast', 'contrast', 'ذَنْب looks at what follows the deed; إِثْم at how it holds you back from good, and it is deliberate; خَطِيئَة at missing the aim; جُنَاح at leaning off the right path. — al-Rāghib pp. 331, 63, 287, 206; Lane pp. 980, 22', 'high');
UPDATE ar_ling_root_lemma_furuq_set SET canonical_ar = 'العِقَابُ وَأَخَوَاتُهُ', updated_at = datetime('now') WHERE id = 'NS:PUNISHMENT:PUNISHMENT' AND canonical_ar IS NULL;
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:NS:PUNISHMENT:PUNISHMENT:contrast', 'NS:PUNISHMENT:PUNISHMENT', 'kmaps_synth', 'contrast', 'contrast', 'عِقَاب is the payback that comes after the deed; عَذَاب is the pain itself; نَكَال is punishment made an example to scare others off; بَأْس is hard force that strikes. — Maqāyīs p.18; al-Rāghib pp. 554, 824, 153', 'high');
UPDATE ar_ling_root_lemma_furuq_set SET canonical_ar = 'الغُفْرَانُ وَالعَفْوُ وَالصَّفْحُ', updated_at = datetime('now') WHERE id = 'NS:TO:TO_FORGIVE_PARDON' AND canonical_ar IS NULL;
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:NS:TO:TO_FORGIVE_PARDON:contrast', 'NS:TO:TO_FORGIVE_PARDON', 'kmaps_synth', 'contrast', 'contrast', 'غَفَرَ covers the sin and shields you from its punishment; عَفَا wipes it out and drops the penalty; صَفَحَ goes further: not even a word of blame. — al-Rāghib p.486 «أبلغ من العفو … وقد يعفو الإنسان ولا يصفح»; pp. 609, 574', 'high');
UPDATE ar_ling_root_lemma_furuq_set SET canonical_ar = 'التَّوْبَةُ وَالإِنَابَةُ وَالرُّجُوعُ', updated_at = datetime('now') WHERE id = 'NS:TO:TO_RETURN' AND canonical_ar IS NULL;
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:NS:TO:TO_RETURN:contrast', 'NS:TO:TO_RETURN', 'kmaps_synth', 'contrast', 'contrast', 'رَجَعَ is the plain word for going back to where you began; تَابَ is turning back from sin; أَنَابَ is turning to God again and again, sincerely; صَارَ is where a thing ends up. — al-Rāghib pp. 342, 169, 827, 498', 'high');
UPDATE ar_ling_root_lemma_furuq_set SET canonical_ar = 'الطَّوْلُ وَالسَّعَةُ وَالفَضْلُ', updated_at = datetime('now') WHERE id = 'NS:SUFFICIENT:SUFFICIENT' AND canonical_ar IS NULL;
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:NS:SUFFICIENT:SUFFICIENT:contrast', 'NS:SUFFICIENT:SUFFICIENT', 'kmaps_synth', 'contrast', 'contrast', 'طَوْل is bounty with reach and power behind it; سَعَة is roominess, having enough; فَضْل is the extra given beyond what is owed. — al-Rāghib pp. 533, 639; Lisān p.4240', 'high');
UPDATE ar_ling_root_lemma_furuq_set SET canonical_ar = 'نَزَّلَ وَأَنْزَلَ', updated_at = datetime('now') WHERE id = 'NS:TO:TO_DESCEND_TO_REVEAL_COME_DOWN' AND canonical_ar IS NULL;
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:NS:TO:TO_DESCEND_TO_REVEAL_COME_DOWN:contrast', 'NS:TO:TO_DESCEND_TO_REVEAL_COME_DOWN', 'kmaps_synth', 'contrast', 'contrast', 'al-Rāghib, al-Zamakhsharī and al-Rāzī: نَزَّلَ is piece by piece, over time, and أَنْزَلَ the general word. Abū Ḥayyān, Ibn ʿĀshūr and al-Ālūsī doubt the rule (see 25:32). — al-Rāghib p.799; at 3:3: al-Kashshāf, al-Rāzī p.137, Abū Ḥayyān, Ibn ʿĀshūr p.147, al-Ālūsī p.76', 'high');
